package com.bank.cache;

// Doubly linked list with sentinel head/tail so every op is O(1) and branch-free.
// Head side = most recently used; tail side = least recently used (eviction end).
class DoublyLinkedList {
    private final Node head = new Node("HEAD", null, 0);
    private final Node tail = new Node("TAIL", null, 0);
    int size = 0;

    DoublyLinkedList() { head.next = tail; tail.prev = head; }

    void addToHead(Node n) {                 // O(1)
        n.prev = head; n.next = head.next;
        head.next.prev = n; head.next = n;
        size++;
    }
    void remove(Node n) {                    // O(1) — node holds its own neighbors
        n.prev.next = n.next; n.next.prev = n.prev;
        size--;
    }
    Node removeTail() {                      // O(1) — least recently used victim
        if (size == 0) return null;
        Node lru = tail.prev;
        remove(lru);
        return lru;
    }
    boolean isEmpty() { return size == 0; }
}
