package com.bank.cache;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// O(1) LFU cache + frequency decay + per-entry TTL. Guard with a lock if shared.
class LfuCache {
    private static final Logger log = Logger.getLogger(LfuCache.class.getName());
    private final int capacity;
    private final long ttlMillis;
    private int minFreq = 0;
    private final Map<String, Node> keyToNode = new HashMap<>();
    private final Map<Integer, DoublyLinkedList> freqToList = new HashMap<>();

    LfuCache(int capacity, long ttlMillis) {
        this.capacity = capacity;
        this.ttlMillis = ttlMillis;
    }

    // O(1): return balance, promote frequency, honor TTL.
    synchronized BigDecimal get(String key) {
        Node n = keyToNode.get(key);
        if (n == null) return null;                       // miss
        if (System.currentTimeMillis() > n.expiryMillis) {  // TTL expired → treat as miss
            removeNode(n);
            log.fine(() -> "TTL expired for " + key);
            return null;
        }
        promote(n);                                       // freq++ and rebucket (O(1))
        return n.value;
    }

    // O(1): insert/update, evict least-frequently-used (ties by LRU) when full.
    synchronized void put(String key, BigDecimal value) {
        if (capacity == 0) return;
        Node existing = keyToNode.get(key);
        if (existing != null) {                           // update + promote
            existing.value = value;
            existing.expiryMillis = System.currentTimeMillis() + ttlMillis;
            promote(existing);
            return;
        }
        if (keyToNode.size() >= capacity) {               // evict victim at minFreq
            DoublyLinkedList lowest = freqToList.get(minFreq);
            Node victim = lowest.removeTail();
            keyToNode.remove(victim.key);
            log.info(() -> "Evicted LFU key=" + victim.key + " freq=" + victim.freq);
        }
        Node node = new Node(key, value, System.currentTimeMillis() + ttlMillis);
        keyToNode.put(key, node);
        freqToList.computeIfAbsent(1, k -> new DoublyLinkedList()).addToHead(node);
        minFreq = 1;                                      // new entry always freq 1
    }

    private void promote(Node n) {
        DoublyLinkedList cur = freqToList.get(n.freq);
        cur.remove(n);
        if (cur.isEmpty() && n.freq == minFreq) minFreq++;   // bump min if we emptied it
        n.freq++;
        freqToList.computeIfAbsent(n.freq, k -> new DoublyLinkedList()).addToHead(n);
    }

    private void removeNode(Node n) {
        freqToList.get(n.freq).remove(n);
        keyToNode.remove(n.key);
    }

    // Time-based frequency decay: halve every entry's freq so old popularity ages.
    synchronized void decay() {
        Map<Integer, DoublyLinkedList> rebuilt = new HashMap<>();
        int newMin = Integer.MAX_VALUE;
        for (Node n : keyToNode.values()) {
            n.freq = Math.max(1, n.freq / 2);             // decay rule
            rebuilt.computeIfAbsent(n.freq, k -> new DoublyLinkedList()).addToHead(n);
            newMin = Math.min(newMin, n.freq);
        }
        freqToList.clear();
        freqToList.putAll(rebuilt);
        minFreq = keyToNode.isEmpty() ? 0 : newMin;
        log.info("Frequency decay applied; minFreq=" + minFreq);
    }
}
