package com.bank.cache;

import java.math.BigDecimal;
import java.util.logging.*;

public class LfuCacheDemo {
    private static final Logger log = Logger.getLogger(LfuCacheDemo.class.getName());

    static {   // clean single-line log format
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        LfuCache cache = new LfuCache(2, 30_000);         // capacity 2, TTL 30s

        cache.put("SAV2001", new BigDecimal("1000000"));  // Rajesh
        cache.put("CUR3001", new BigDecimal("250000"));   // Priya

        cache.get("SAV2001");                             // Rajesh freq → 2
        cache.get("SAV2001");                             // Rajesh freq → 3
        cache.get("CUR3001");                             // Priya  freq → 2

        // Cache full; adding a 3rd key evicts the LFU one (Priya, freq 2 < Rajesh 3)
        cache.put("SAV9999", new BigDecimal("500000"));
        log.info("Priya after eviction = " + cache.get("CUR3001"));   // null (evicted)
        log.info("Rajesh still cached   = " + cache.get("SAV2001"));

        cache.decay();                                    // age all frequencies
        log.info("Rajesh after decay    = " + cache.get("SAV2001"));
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
